#!/bin/bash
# Generated by Claude Fable 5.1 (Anthropic)
# cpuset_probe.sh <out.log> — every 2 s: "<epoch> <app_busy> <obs_busy> <rest_busy>"
# busy jiffies (user+nice+system+irq+softirq) summed per CPU set from /proc/stat.
# Sets from FISH_APP_CPUS / FISH_OBS_CPUS ("0,2,4-6" syntax). Pins itself to the
# observer set. Consumed by analyze_overhead.cpuset_busiest_window.
OUT=${1:?out file}
[ -n "$FISH_OBS_CPUS" ] && taskset -pc "$FISH_OBS_CPUS" $$ >/dev/null 2>&1
while :; do
  printf "%s " "$(date +%s.%N)"
  awk -v app="$FISH_APP_CPUS" -v obs="$FISH_OBS_CPUS" '
    function inset(c, s,   n, i, parts, ab, a, b) { n = split(s, parts, ",");
      for (i = 1; i <= n; i++) { if (index(parts[i], "-")) { split(parts[i], ab, "-"); a = ab[1]+0; b = ab[2]+0 } else { a = parts[i]+0; b = a }
        if (c >= a && c <= b) return 1 } return 0 }
    /^cpu[0-9]+ / { c = substr($1, 4)+0; busy = $2+$3+$4+$7+$8; if (inset(c, app)) A += busy; else if (inset(c, obs)) O += busy; else X += busy }
    END { printf "%d %d %d\n", A, O, X }' /proc/stat
  sleep 2
done >> "$OUT" 2>/dev/null
